INSERT INTO clues (dish_id, order_index, text) VALUES
((SELECT id FROM dishes WHERE slug='denver-omelette'), 1, 'Folded on the flat-top and slid out next to a pile of hash browns.'),
((SELECT id FROM dishes WHERE slug='denver-omelette'), 2, 'Southwestern diners also list it as the Western, and no one has pinned down who made it first.'),
((SELECT id FROM dishes WHERE slug='denver-omelette'), 3, 'Slapped between slices of toast instead, the same filling becomes a sandwich named for the same city.'),
((SELECT id FROM dishes WHERE slug='denver-omelette'), 4, 'You fry diced ham, onion and green bell pepper on the griddle, pour beaten eggs over them, and fold it with cheese.'),
((SELECT id FROM dishes WHERE slug='denver-omelette'), 5, 'A fluffy ham, onion and green pepper fold from American diners, named for a Colorado city.'),
((SELECT id FROM dishes WHERE slug='dutch-baby'), 1, 'Puffed over the skillet walls, it sinks the moment it reaches the table.'),
((SELECT id FROM dishes WHERE slug='dutch-baby'), 2, 'Manca''s Cafe in Seattle served it early in the 1900s, and one story blames its name on the owner''s daughter.'),
((SELECT id FROM dishes WHERE slug='dutch-baby'), 3, 'No baking powder or yeast goes in; eggs and a blazing hot pan do all the lifting.'),
((SELECT id FROM dishes WHERE slug='dutch-baby'), 4, 'You blend eggs, flour and milk, pour the batter into a buttered cast-iron pan, and bake it hot.'),
((SELECT id FROM dishes WHERE slug='dutch-baby'), 5, 'An American oven pancake, golden and craggy, finished with lemon, butter and powdered sugar.'),
((SELECT id FROM dishes WHERE slug='salisbury-steak'), 1, 'An oval patty under brown gravy in a TV-dinner tray.'),
((SELECT id FROM dishes WHERE slug='salisbury-steak'), 2, 'A doctor who preached a meat-heavy diet called his version ''muscle pulp of beef'', and his name stuck by 1897.'),
((SELECT id FROM dishes WHERE slug='salisbury-steak'), 3, 'Federal rules say a packaged one must be at least 65% meat, with up to a quarter of that pork.'),
((SELECT id FROM dishes WHERE slug='salisbury-steak'), 4, 'You mix ground beef with onion, breadcrumbs and egg, shape ovals, sear them, and simmer them in mushroom gravy.'),
((SELECT id FROM dishes WHERE slug='salisbury-steak'), 5, 'Ground beef ovals smothered in brown mushroom gravy beside mashed potatoes, an American diner plate.'),
((SELECT id FROM dishes WHERE slug='french-dip'), 1, 'Arrives with a mug of hot broth on the side for dunking.'),
((SELECT id FROM dishes WHERE slug='french-dip'), 2, 'Two Los Angeles restaurants, both opened in 1908, still claim it, and the fight has never been settled.'),
((SELECT id FROM dishes WHERE slug='french-dip'), 3, 'One story has a server drop the roll in the meat drippings; the rival credits a customer with sore gums.'),
((SELECT id FROM dishes WHERE slug='french-dip'), 4, 'You pile thin roast beef on a split baguette and serve it with the pan juices, au jus, for dipping.'),
((SELECT id FROM dishes WHERE slug='french-dip'), 5, 'Thin roast beef on a crusty roll with a cup of jus, an American sandwich from Los Angeles.'),
((SELECT id FROM dishes WHERE slug='monte-cristo'), 1, 'Sugar-dusted and served with jam, though there''s ham inside.'),
((SELECT id FROM dishes WHERE slug='monte-cristo'), 2, 'A 1923 restaurant trade publication is the first to name it, a variation on a French grilled sandwich.'),
((SELECT id FROM dishes WHERE slug='monte-cristo'), 3, 'Disneyland''s Blue Bayou restaurant spread its fame, serving it battered and fried.'),
((SELECT id FROM dishes WHERE slug='monte-cristo'), 4, 'You stack ham, turkey and Swiss between bread, dip it in beaten egg, and fry it like French toast.'),
((SELECT id FROM dishes WHERE slug='monte-cristo'), 5, 'A ham and turkey sandwich fried in egg batter and sugared, with jam, from American diners.'),
((SELECT id FROM dishes WHERE slug='muffuletta'), 1, 'So big and round it comes cut in quarters.'),
((SELECT id FROM dishes WHERE slug='muffuletta'), 2, 'Sicilian immigrant Salvatore Lupo is credited with building it at his New Orleans grocery in 1906.'),
((SELECT id FROM dishes WHERE slug='muffuletta'), 3, 'An oily chopped olive salad soaks through the bread, with cauliflower, carrot and celery in it.'),
((SELECT id FROM dishes WHERE slug='muffuletta'), 4, 'You split a round sesame loaf, pile on salami, ham, mortadella and provolone, and spoon olive salad on top.'),
((SELECT id FROM dishes WHERE slug='muffuletta'), 5, 'New Orleans''s giant Sicilian-American sandwich of cured meats and olive salad on a sesame round.'),
((SELECT id FROM dishes WHERE slug='mozzarella-sticks'), 1, 'Hot fried batons that stretch into long strings when you pull one apart.'),
((SELECT id FROM dishes WHERE slug='mozzarella-sticks'), 2, 'A Paris household guide from 1393 fries battered cheese, though historians doubt it was anything like this.'),
((SELECT id FROM dishes WHERE slug='mozzarella-sticks'), 3, 'Mass-produced cheese and faster fryers made them a 1970s appetizer, most likely in the United States.'),
((SELECT id FROM dishes WHERE slug='mozzarella-sticks'), 4, 'You coat fingers of mozzarella in flour, egg and breadcrumbs, freeze them, then deep-fry them fast.'),
((SELECT id FROM dishes WHERE slug='mozzarella-sticks'), 5, 'An American bar appetizer of crumb-coated cheese fingers with marinara for dunking.'),
((SELECT id FROM dishes WHERE slug='jalapeno-poppers'), 1, 'Green halves that look cooling until the heat arrives a second later.'),
((SELECT id FROM dishes WHERE slug='jalapeno-poppers'), 2, 'A frozen-food company trademarked the name in 1992; Texans had called them armadillo eggs for 20 years.'),
((SELECT id FROM dishes WHERE slug='jalapeno-poppers'), 3, 'Cooks treat it as a Tex-Mex cousin of the chile relleno, the stuffed pepper of Mexico.'),
((SELECT id FROM dishes WHERE slug='jalapeno-poppers'), 4, 'You halve and seed the peppers, pack them with cream cheese and cheddar, then bread and fry them.'),
((SELECT id FROM dishes WHERE slug='jalapeno-poppers'), 5, 'Hot green chiles packed with melted cheese under a crisp crust, an American bar snack.'),
((SELECT id FROM dishes WHERE slug='spam-musubi'), 1, 'Rice pressed into a block, belted with a black strip, eaten one-handed.'),
((SELECT id FROM dishes WHERE slug='spam-musubi'), 2, 'Canned meat came to Hawaii with the troops in World War II, and two women in the 1980s are credited with this.'),
((SELECT id FROM dishes WHERE slug='spam-musubi'), 3, 'It follows Japanese onigiri, but the slice on top comes from a can.'),
((SELECT id FROM dishes WHERE slug='spam-musubi'), 4, 'You fry slices of canned pork in soy sauce and sugar, press them onto rice in a mold, and wrap a nori strip around.'),
((SELECT id FROM dishes WHERE slug='spam-musubi'), 5, 'Hawaii''s grab-and-go snack of glazed canned meat on rice, an American take on onigiri.'),
((SELECT id FROM dishes WHERE slug='roast-turkey'), 1, 'Carved whole at the head of the table, with the wishbone saved for later.'),
((SELECT id FROM dishes WHERE slug='roast-turkey'), 2, 'Each November a president pardons a live one at the White House, and the rest go in the oven.'),
((SELECT id FROM dishes WHERE slug='roast-turkey'), 3, 'Diners pile the leftovers onto bread, under gravy, as an open-faced hot sandwich.'),
((SELECT id FROM dishes WHERE slug='roast-turkey'), 4, 'You roast the bird for hours, basting it with butter, with bread stuffing inside and pan drippings saved for gravy.'),
((SELECT id FROM dishes WHERE slug='roast-turkey'), 5, 'The American Thanksgiving centerpiece, carved white and dark meat with stuffing and cranberry sauce.'),
((SELECT id FROM dishes WHERE slug='strawberry-shortcake'), 1, 'A split, sugared biscuit spilling fruit juice and cream onto the plate.'),
((SELECT id FROM dishes WHERE slug='strawberry-shortcake'), 2, 'An 1845 recipe first paired the fruit with cake, and leavened biscuit bases took over by the 1850s.'),
((SELECT id FROM dishes WHERE slug='strawberry-shortcake'), 3, 'Bakeries in Asia sell sponge-cake versions under the same name, with no biscuit in sight.'),
((SELECT id FROM dishes WHERE slug='strawberry-shortcake'), 4, 'You bake rich buttery biscuits, split them warm, and layer them with sugared sliced fruit and whipped cream.'),
((SELECT id FROM dishes WHERE slug='strawberry-shortcake'), 5, 'An American summer dessert, a crumbly split biscuit under macerated fruit and whipped cream.'),
((SELECT id FROM dishes WHERE slug='boston-cream-pie'), 1, 'Called a pie, but you slice it like the layer cake it is.'),
((SELECT id FROM dishes WHERE slug='boston-cream-pie'), 2, 'A French chef at the Parker House Hotel is credited with it, possibly for the hotel''s 1856 opening.'),
((SELECT id FROM dishes WHERE slug='boston-cream-pie'), 3, 'Massachusetts made it the state dessert in 1996, and its doughnut cousin got the same honour in 2003.'),
((SELECT id FROM dishes WHERE slug='boston-cream-pie'), 4, 'You split a sponge cake, fill it with vanilla custard, and pour a chocolate glaze over the top.'),
((SELECT id FROM dishes WHERE slug='boston-cream-pie'), 5, 'A Massachusetts hotel''s layer cake with a cream middle and glossy dark top, an American classic.'),
((SELECT id FROM dishes WHERE slug='red-velvet-cake'), 1, 'Deep crimson crumb under thick white frosting.'),
((SELECT id FROM dishes WHERE slug='red-velvet-cake'), 2, 'A dye maker spread the recipe across the country during World War II to sell its red coloring.'),
((SELECT id FROM dishes WHERE slug='red-velvet-cake'), 3, 'A 1989 film''s armadillo-shaped groom''s cake revived it after a dye cancer scare had sunk it.'),
((SELECT id FROM dishes WHERE slug='red-velvet-cake'), 4, 'You beat cocoa, buttermilk, vinegar and red coloring into a batter, bake the layers, and frost them with cream cheese.'),
((SELECT id FROM dishes WHERE slug='red-velvet-cake'), 5, 'Scarlet crumb under tangy cream cheese frosting, an American layer cake of the South.'),
((SELECT id FROM dishes WHERE slug='bananas-foster'), 1, 'A dessert set alight beside your table by the waiter.'),
((SELECT id FROM dishes WHERE slug='bananas-foster'), 2, 'Chef Paul Blangé and Ella Brennan created it in 1951 at Brennan''s, from a dish Ella''s mother cooked at home.'),
((SELECT id FROM dishes WHERE slug='bananas-foster'), 3, 'It is named for the chairman of the city''s crime commission, a friend of the restaurant''s owner.'),
((SELECT id FROM dishes WHERE slug='bananas-foster'), 4, 'You melt butter, brown sugar and cinnamon in a pan, add the sliced fruit, pour in rum and set it alight.'),
((SELECT id FROM dishes WHERE slug='bananas-foster'), 5, 'Fruit flamed in rum and brown sugar over vanilla ice cream, a New Orleans American classic.');
